    with_publishers,
    publisher_values=None,
    campaign_suffixes=None,
    numeric_strings=False,
    numeric_aliases=False,
):
    publishers = publisher_values or (
        ("facebook", "facebook", "instagram", "instagram") if with_publishers else (None,) * 4
    )
    raw_rows = []
